def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(row.count(x) for row in grid))
    out = [row[:] for row in grid]

    for r in range(h):
        marks = [c for c in range(w) if grid[r][c] != bg]
        if len(marks) >= 2:
            for c in range(min(marks) + 1, max(marks)):
                if grid[r][c] == bg:
                    out[r][c] = 3

    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] != bg]
        if len(marks) >= 2:
            for r in range(min(marks) + 1, max(marks)):
                if grid[r][c] == bg:
                    out[r][c] = 3

    return out
